/** Default calibration for frames that have no measurement (e.g. custom shop frames). */
export const DEFAULT_FRAME_CALIB = { fill: 0.92, cy: 0.5 };

export function calibForLevel(level: number) {
  return FRAME_CALIB[Math.max(1, Math.min(100, Math.round(level)))] ?? DEFAULT_FRAME_CALIB;
}
